import{_ as e,o as s,c as o,ag as i}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"Repair Station Business","description":"","frontmatter":{},"headers":[],"relativePath":"pt/repair-station-business/index.md","filePath":"pt/repair-station-business/index.md"}'),t={name:"pt/repair-station-business/index.md"};function r(n,a,p,d,l,c){return s(),o("div",null,[...a[0]||(a[0]=[i(`<h1 id="repair-station-business" tabindex="-1">Repair Station Business <a class="header-anchor" href="#repair-station-business" aria-label="Permalink to &quot;Repair Station Business&quot;">​</a></h1><p>A extensão paga da <a href="/pt/repair-station/">Repair Station</a>: os jogadores compram estações de reparação, abastecem-nas de peças, definem os preços e levantam a caixa. Tudo se gere a partir de um tablet na estação, e cada definição edita-se no jogo.</p><h2 id="funcionalidades" tabindex="-1">Funcionalidades <a class="header-anchor" href="#funcionalidades" aria-label="Permalink to &quot;Funcionalidades&quot;">​</a></h2><ul><li><strong>Estações à venda</strong>: escolhe quais Repair Stations podem ser compradas e por que preço. Veja <a href="/pt/repair-station-business/ownership">Propriedade</a>.</li><li><strong>Tablet do proprietário</strong>: stock, caixa, últimas operações, preços, nome e venda da estação, no mesmo sítio.</li><li><strong>Peças</strong>: cada reparação gasta peças do stock da estação, compradas com a conta bancária ou entregues como objetos. Veja <a href="/pt/repair-station-business/stock">Stock</a>.</li><li><strong>Preços do proprietário</strong>: cada proprietário define uma percentagem do preço base, dentro dos limites que escolher, e é retido um imposto em cada pagamento.</li><li><strong>Finais justos</strong>: um proprietário que vende, é expulso ou fica inativo é reembolsado de parte do preço de compra mais a caixa, mesmo offline.</li><li><strong>Painel de administração</strong>: coloque estações à venda, altere o preço, defina o stock das estações com proprietário ou expulse um proprietário sem sair do jogo.</li><li><strong>API HTTP e webhooks</strong>: estações, registo e estatísticas para o seu site, e uma mensagem Discord por cada compra, reposição, levantamento e perda de estação. Veja <a href="/pt/repair-station-business/api">API e webhooks</a>.</li><li><strong>Seis idiomas</strong>: inglês, francês, espanhol, português, polaco, alemão.</li></ul><h2 id="compatibilidade" tabindex="-1">Compatibilidade <a class="header-anchor" href="#compatibilidade" aria-label="Permalink to &quot;Compatibilidade&quot;">​</a></h2><ul><li>Frameworks: ESX Legacy, QBCore, QBox, ox_core, detetados automaticamente.</li><li>Dependências: oxmysql, <code>nay_lib</code> e a <a href="/pt/repair-station/">Repair Station</a> (<code>nay_repair</code>), incluídos na sua compra dos scripts.</li></ul><h2 id="instalacao" tabindex="-1">Instalação <a class="header-anchor" href="#instalacao" aria-label="Permalink to &quot;Instalação&quot;">​</a></h2><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_repair</span></span>
<span class="line"><span>ensure nay_repair_business</span></span></code></pre></div><p>Os passos completos estão na página <a href="/pt/getting-started">Primeiros passos</a>. Depois atribua-se <code>nay_repair_business.config</code> (ou <code>nay.admin</code>) e abra <code>/nay</code>, ou escreva <code>/nay:repairbusiness</code> para o painel de administração. Marque no painel as estações que quer vender: até lá, as estações comportam-se como simples Repair Stations.</p>`,9)])])}const g=e(t,[["render",r]]);export{m as __pageData,g as default};
